INSERT INTO portal_practice_questions(code,subject_id,content) SELECT 'FAM-VRB-01',id,'{"id":"70000000-0000-0000-0000-000000000001","code":"FAM-VRB-01","stem":"Which word does not belong with the others?","explanation":"Car, Bus, and Truck are motor vehicles; Bicycle is non-motorized.","stem_image_url":null,"options":[{"id":"FAM-VRB-01-A","label":"A","text":"Car","is_correct":false,"image_url":null},{"id":"FAM-VRB-01-B","label":"B","text":"Bus","is_correct":false,"image_url":null},{"id":"FAM-VRB-01-C","label":"C","text":"Bicycle","is_correct":true,"image_url":null},{"id":"FAM-VRB-01-D","label":"D","text":"Truck","is_correct":false,"image_url":null}]}'::jsonb || jsonb_build_object('subject_name',name) FROM subjects WHERE code='INTELLIGENCE_VERBAL' ON CONFLICT DO NOTHING;
INSERT INTO portal_practice_questions(code,subject_id,content) SELECT 'FAM-VRB-02',id,'{"id":"70000000-0000-0000-0000-000000000012","code":"FAM-VRB-02","stem":"If ARMY is coded as 1-18-13-25, how is NAVY coded?","explanation":"Each letter corresponds to its position in the alphabet: N=14, A=1, V=22, Y=25.","stem_image_url":null,"options":[{"id":"FAM-VRB-02-A","label":"A","text":"14-1-22-25","is_correct":true,"image_url":null},{"id":"FAM-VRB-02-B","label":"B","text":"13-1-21-25","is_correct":false,"image_url":null},{"id":"FAM-VRB-02-C","label":"C","text":"14-2-22-26","is_correct":false,"image_url":null},{"id":"FAM-VRB-02-D","label":"D","text":"15-1-22-25","is_correct":false,"image_url":null}]}'::jsonb || jsonb_build_object('subject_name',name) FROM subjects WHERE code='INTELLIGENCE_VERBAL' ON CONFLICT DO NOTHING;
INSERT INTO portal_practice_questions(code,subject_id,content) SELECT 'FAM-VRB-03',id,'{"id":"70000000-0000-0000-0000-000000000013","code":"FAM-VRB-03","stem":"Pilot is to Aircraft as Captain is to:","explanation":"A pilot commands an aircraft, while a ship captain commands a ship/vessel.","stem_image_url":null,"options":[{"id":"FAM-VRB-03-A","label":"A","text":"Runway","is_correct":false,"image_url":null},{"id":"FAM-VRB-03-B","label":"B","text":"Ship","is_correct":true,"image_url":null},{"id":"FAM-VRB-03-C","label":"C","text":"Hangar","is_correct":false,"image_url":null},{"id":"FAM-VRB-03-D","label":"D","text":"Submarine Base","is_correct":false,"image_url":null}]}'::jsonb || jsonb_build_object('subject_name',name) FROM subjects WHERE code='INTELLIGENCE_VERBAL' ON CONFLICT DO NOTHING;
INSERT INTO portal_practice_questions(code,subject_id,content) SELECT 'FAM-VRB-04',id,'{"id":"70000000-0000-0000-0000-000000000014","code":"FAM-VRB-04","stem":"What comes next in the sequence: 3, 6, 12, 24, ?","explanation":"Each term is multiplied by 2: 24 * 2 = 48.","stem_image_url":null,"options":[{"id":"FAM-VRB-04-A","label":"A","text":"36","is_correct":false,"image_url":null},{"id":"FAM-VRB-04-B","label":"B","text":"42","is_correct":false,"image_url":null},{"id":"FAM-VRB-04-C","label":"C","text":"48","is_correct":true,"image_url":null},{"id":"FAM-VRB-04-D","label":"D","text":"52","is_correct":false,"image_url":null}]}'::jsonb || jsonb_build_object('subject_name',name) FROM subjects WHERE code='INTELLIGENCE_VERBAL' ON CONFLICT DO NOTHING;
INSERT INTO portal_practice_questions(code,subject_id,content) SELECT 'FAM-VRB-05',id,'{"id":"70000000-0000-0000-0000-000000000015","code":"FAM-VRB-05","stem":"Courage is to Cowardice as Loyalty is to:","explanation":"Antonyms: Courage opposes Cowardice; Loyalty opposes Treachery.","stem_image_url":null,"options":[{"id":"FAM-VRB-05-A","label":"A","text":"Bravery","is_correct":false,"image_url":null},{"id":"FAM-VRB-05-B","label":"B","text":"Treachery","is_correct":true,"image_url":null},{"id":"FAM-VRB-05-C","label":"C","text":"Honour","is_correct":false,"image_url":null},{"id":"FAM-VRB-05-D","label":"D","text":"Devotion","is_correct":false,"image_url":null}]}'::jsonb || jsonb_build_object('subject_name',name) FROM subjects WHERE code='INTELLIGENCE_VERBAL' ON CONFLICT DO NOTHING;
INSERT INTO portal_practice_questions(code,subject_id,content) SELECT 'FAM-NVR-01',id,'{"id":"70000000-0000-0000-0000-000000000002","code":"FAM-NVR-01","stem":"Identify the odd shape out in pattern: Circle, Square, Pentagon, Oval, Triangle.","explanation":"Square, Pentagon, and Triangle are straight-line polygons; Oval and Circle are curved conic shapes.","stem_image_url":null,"options":[{"id":"FAM-NVR-01-A","label":"A","text":"Equilateral Triangle","is_correct":false,"image_url":null},{"id":"FAM-NVR-01-B","label":"B","text":"Regular Hexagon","is_correct":false,"image_url":null},{"id":"FAM-NVR-01-C","label":"C","text":"Circle","is_correct":true,"image_url":null},{"id":"FAM-NVR-01-D","label":"D","text":"Square","is_correct":false,"image_url":null}]}'::jsonb || jsonb_build_object('subject_name',name) FROM subjects WHERE code='INTELLIGENCE_NON_VERBAL' ON CONFLICT DO NOTHING;
INSERT INTO portal_practice_questions(code,subject_id,content) SELECT 'FAM-NVR-02',id,'{"id":"70000000-0000-0000-0000-000000000022","code":"FAM-NVR-02","stem":"A clock hand rotates 90 degrees clockwise from 12:00. Where does it point?","explanation":"90 degrees clockwise rotation from 12:00 points to 3:00.","stem_image_url":null,"options":[{"id":"FAM-NVR-02-A","label":"A","text":"3:00","is_correct":true,"image_url":null},{"id":"FAM-NVR-02-B","label":"B","text":"6:00","is_correct":false,"image_url":null},{"id":"FAM-NVR-02-C","label":"C","text":"9:00","is_correct":false,"image_url":null},{"id":"FAM-NVR-02-D","label":"D","text":"1:30","is_correct":false,"image_url":null}]}'::jsonb || jsonb_build_object('subject_name',name) FROM subjects WHERE code='INTELLIGENCE_NON_VERBAL' ON CONFLICT DO NOTHING;
INSERT INTO portal_practice_questions(code,subject_id,content) SELECT 'FAM-NVR-03',id,'{"id":"70000000-0000-0000-0000-000000000023","code":"FAM-NVR-03","stem":"In a matrix, shapes increase sides: Triangle (3), Square (4), Pentagon (5). What comes next?","explanation":"A shape with 6 sides: Hexagon.","stem_image_url":null,"options":[{"id":"FAM-NVR-03-A","label":"A","text":"Heptagon","is_correct":false,"image_url":null},{"id":"FAM-NVR-03-B","label":"B","text":"Hexagon","is_correct":true,"image_url":null},{"id":"FAM-NVR-03-C","label":"C","text":"Octagon","is_correct":false,"image_url":null},{"id":"FAM-NVR-03-D","label":"D","text":"Decagon","is_correct":false,"image_url":null}]}'::jsonb || jsonb_build_object('subject_name',name) FROM subjects WHERE code='INTELLIGENCE_NON_VERBAL' ON CONFLICT DO NOTHING;
INSERT INTO portal_practice_questions(code,subject_id,content) SELECT 'FAM-NVR-04',id,'{"id":"70000000-0000-0000-0000-000000000024","code":"FAM-NVR-04","stem":"Which figure represents a mirror reflection across the vertical axis?","explanation":"In vertical axis reflection, left and right invert while top and bottom remain stationary.","stem_image_url":null,"options":[{"id":"FAM-NVR-04-A","label":"A","text":"Lateral Inversion","is_correct":true,"image_url":null},{"id":"FAM-NVR-04-B","label":"B","text":"Vertical Inversion","is_correct":false,"image_url":null},{"id":"FAM-NVR-04-C","label":"C","text":"180 Degree Rotation","is_correct":false,"image_url":null},{"id":"FAM-NVR-04-D","label":"D","text":"Direct Translation","is_correct":false,"image_url":null}]}'::jsonb || jsonb_build_object('subject_name',name) FROM subjects WHERE code='INTELLIGENCE_NON_VERBAL' ON CONFLICT DO NOTHING;
INSERT INTO portal_practice_questions(code,subject_id,content) SELECT 'FAM-NVR-05',id,'{"id":"70000000-0000-0000-0000-000000000025","code":"FAM-NVR-05","stem":"A square has two diagonals. Into how many non-overlapping triangles is it divided?","explanation":"Two diagonal lines intersect in the center dividing a square into 4 congruent triangles.","stem_image_url":null,"options":[{"id":"FAM-NVR-05-A","label":"A","text":"2","is_correct":false,"image_url":null},{"id":"FAM-NVR-05-B","label":"B","text":"4","is_correct":true,"image_url":null},{"id":"FAM-NVR-05-C","label":"C","text":"6","is_correct":false,"image_url":null},{"id":"FAM-NVR-05-D","label":"D","text":"8","is_correct":false,"image_url":null}]}'::jsonb || jsonb_build_object('subject_name',name) FROM subjects WHERE code='INTELLIGENCE_NON_VERBAL' ON CONFLICT DO NOTHING;
INSERT INTO portal_practice_questions(code,subject_id,content) SELECT 'FAM-PHY-01',id,'{"id":"70000000-0000-0000-0000-000000000003","code":"FAM-PHY-01","stem":"What is the SI unit of Force?","explanation":"The SI unit of force is the Newton (N), equal to 1 kg * m / s^2.","stem_image_url":null,"options":[{"id":"FAM-PHY-01-A","label":"A","text":"Joule","is_correct":false,"image_url":null},{"id":"FAM-PHY-01-B","label":"B","text":"Newton","is_correct":true,"image_url":null},{"id":"FAM-PHY-01-C","label":"C","text":"Watt","is_correct":false,"image_url":null},{"id":"FAM-PHY-01-D","label":"D","text":"Pascal","is_correct":false,"image_url":null}]}'::jsonb || jsonb_build_object('subject_name',name) FROM subjects WHERE code='ACADEMIC_PHYSICS' ON CONFLICT DO NOTHING;
INSERT INTO portal_practice_questions(code,subject_id,content) SELECT 'FAM-PHY-02',id,'{"id":"70000000-0000-0000-0000-000000000032","code":"FAM-PHY-02","stem":"What is the rate of change of displacement called?","explanation":"Displacement divided by time is Velocity (a vector quantity).","stem_image_url":null,"options":[{"id":"FAM-PHY-02-A","label":"A","text":"Speed","is_correct":false,"image_url":null},{"id":"FAM-PHY-02-B","label":"B","text":"Acceleration","is_correct":false,"image_url":null},{"id":"FAM-PHY-02-C","label":"C","text":"Velocity","is_correct":true,"image_url":null},{"id":"FAM-PHY-02-D","label":"D","text":"Momentum","is_correct":false,"image_url":null}]}'::jsonb || jsonb_build_object('subject_name',name) FROM subjects WHERE code='ACADEMIC_PHYSICS' ON CONFLICT DO NOTHING;
INSERT INTO portal_practice_questions(code,subject_id,content) SELECT 'FAM-PHY-03',id,'{"id":"70000000-0000-0000-0000-000000000033","code":"FAM-PHY-03","stem":"According to Newton''s Third Law, action and reaction forces:","explanation":"Action and reaction are equal in magnitude, opposite in direction, and act on two different bodies.","stem_image_url":null,"options":[{"id":"FAM-PHY-03-A","label":"A","text":"Act on the same body","is_correct":false,"image_url":null},{"id":"FAM-PHY-03-B","label":"B","text":"Act on different bodies","is_correct":true,"image_url":null},{"id":"FAM-PHY-03-C","label":"C","text":"Cancel each other out","is_correct":false,"image_url":null},{"id":"FAM-PHY-03-D","label":"D","text":"Have unequal magnitudes","is_correct":false,"image_url":null}]}'::jsonb || jsonb_build_object('subject_name',name) FROM subjects WHERE code='ACADEMIC_PHYSICS' ON CONFLICT DO NOTHING;
INSERT INTO portal_practice_questions(code,subject_id,content) SELECT 'FAM-PHY-04',id,'{"id":"70000000-0000-0000-0000-000000000034","code":"FAM-PHY-04","stem":"What is the speed of light in vacuum approximately?","explanation":"The speed of light c is approximately 3 * 10^8 meters per second.","stem_image_url":null,"options":[{"id":"FAM-PHY-04-A","label":"A","text":"3 * 10^6 m/s","is_correct":false,"image_url":null},{"id":"FAM-PHY-04-B","label":"B","text":"3 * 10^8 m/s","is_correct":true,"image_url":null},{"id":"FAM-PHY-04-C","label":"C","text":"3 * 10^10 m/s","is_correct":false,"image_url":null},{"id":"FAM-PHY-04-D","label":"D","text":"3 * 10^4 m/s","is_correct":false,"image_url":null}]}'::jsonb || jsonb_build_object('subject_name',name) FROM subjects WHERE code='ACADEMIC_PHYSICS' ON CONFLICT DO NOTHING;
INSERT INTO portal_practice_questions(code,subject_id,content) SELECT 'FAM-PHY-05',id,'{"id":"70000000-0000-0000-0000-000000000035","code":"FAM-PHY-05","stem":"In an electric circuit, Ohm''s law is represented by which formula?","explanation":"Ohm''s Law states Voltage (V) = Current (I) * Resistance (R).","stem_image_url":null,"options":[{"id":"FAM-PHY-05-A","label":"A","text":"V = I * R","is_correct":true,"image_url":null},{"id":"FAM-PHY-05-B","label":"B","text":"V = I / R","is_correct":false,"image_url":null},{"id":"FAM-PHY-05-C","label":"C","text":"I = V * R","is_correct":false,"image_url":null},{"id":"FAM-PHY-05-D","label":"D","text":"R = V * I","is_correct":false,"image_url":null}]}'::jsonb || jsonb_build_object('subject_name',name) FROM subjects WHERE code='ACADEMIC_PHYSICS' ON CONFLICT DO NOTHING;
INSERT INTO portal_practice_questions(code,subject_id,content) SELECT 'FAM-MTH-01',id,'{"id":"70000000-0000-0000-0000-000000000004","code":"FAM-MTH-01","stem":"If 2x + 6 = 16, what is the value of x?","explanation":"2x = 16 - 6 = 10, hence x = 10 / 2 = 5.","stem_image_url":null,"options":[{"id":"FAM-MTH-01-A","label":"A","text":"4","is_correct":false,"image_url":null},{"id":"FAM-MTH-01-B","label":"B","text":"5","is_correct":true,"image_url":null},{"id":"FAM-MTH-01-C","label":"C","text":"6","is_correct":false,"image_url":null},{"id":"FAM-MTH-01-D","label":"D","text":"8","is_correct":false,"image_url":null}]}'::jsonb || jsonb_build_object('subject_name',name) FROM subjects WHERE code='ACADEMIC_MATH' ON CONFLICT DO NOTHING;
INSERT INTO portal_practice_questions(code,subject_id,content) SELECT 'FAM-MTH-02',id,'{"id":"70000000-0000-0000-0000-000000000042","code":"FAM-MTH-02","stem":"What is the derivative of x^3 with respect to x?","explanation":"Power rule: d/dx(x^n) = n * x^(n-1). For x^3, derivative is 3x^2.","stem_image_url":null,"options":[{"id":"FAM-MTH-02-A","label":"A","text":"3x^2","is_correct":true,"image_url":null},{"id":"FAM-MTH-02-B","label":"B","text":"x^2","is_correct":false,"image_url":null},{"id":"FAM-MTH-02-C","label":"C","text":"3x","is_correct":false,"image_url":null},{"id":"FAM-MTH-02-D","label":"D","text":"6x","is_correct":false,"image_url":null}]}'::jsonb || jsonb_build_object('subject_name',name) FROM subjects WHERE code='ACADEMIC_MATH' ON CONFLICT DO NOTHING;
INSERT INTO portal_practice_questions(code,subject_id,content) SELECT 'FAM-MTH-03',id,'{"id":"70000000-0000-0000-0000-000000000043","code":"FAM-MTH-03","stem":"What is the value of sin(90 degrees)?","explanation":"In trigonometry, sin(90°) = 1.","stem_image_url":null,"options":[{"id":"FAM-MTH-03-A","label":"A","text":"0","is_correct":false,"image_url":null},{"id":"FAM-MTH-03-B","label":"B","text":"0.5","is_correct":false,"image_url":null},{"id":"FAM-MTH-03-C","label":"C","text":"1","is_correct":true,"image_url":null},{"id":"FAM-MTH-03-D","label":"D","text":"Undefined","is_correct":false,"image_url":null}]}'::jsonb || jsonb_build_object('subject_name',name) FROM subjects WHERE code='ACADEMIC_MATH' ON CONFLICT DO NOTHING;
INSERT INTO portal_practice_questions(code,subject_id,content) SELECT 'FAM-MTH-04',id,'{"id":"70000000-0000-0000-0000-000000000044","code":"FAM-MTH-04","stem":"The sum of interior angles of a triangle is always:","explanation":"A Euclidean triangle''s interior angles always sum to 180 degrees.","stem_image_url":null,"options":[{"id":"FAM-MTH-04-A","label":"A","text":"90°","is_correct":false,"image_url":null},{"id":"FAM-MTH-04-B","label":"B","text":"180°","is_correct":true,"image_url":null},{"id":"FAM-MTH-04-C","label":"C","text":"270°","is_correct":false,"image_url":null},{"id":"FAM-MTH-04-D","label":"D","text":"360°","is_correct":false,"image_url":null}]}'::jsonb || jsonb_build_object('subject_name',name) FROM subjects WHERE code='ACADEMIC_MATH' ON CONFLICT DO NOTHING;
INSERT INTO portal_practice_questions(code,subject_id,content) SELECT 'FAM-MTH-05',id,'{"id":"70000000-0000-0000-0000-000000000045","code":"FAM-MTH-05","stem":"What is the area of a circle with radius r?","explanation":"The formula for the area of a circle is π * r^2.","stem_image_url":null,"options":[{"id":"FAM-MTH-05-A","label":"A","text":"2 * π * r","is_correct":false,"image_url":null},{"id":"FAM-MTH-05-B","label":"B","text":"π * r^2","is_correct":true,"image_url":null},{"id":"FAM-MTH-05-C","label":"C","text":"π * d","is_correct":false,"image_url":null},{"id":"FAM-MTH-05-D","label":"D","text":"4/3 * π * r^3","is_correct":false,"image_url":null}]}'::jsonb || jsonb_build_object('subject_name',name) FROM subjects WHERE code='ACADEMIC_MATH' ON CONFLICT DO NOTHING;
INSERT INTO portal_practice_questions(code,subject_id,content) SELECT 'FAM-ENG-01',id,'{"id":"70000000-0000-0000-0000-000000000005","code":"FAM-ENG-01","stem":"Choose the synonym for \"VALIANT\":","explanation":"Valiant means courageous, determined, or brave in battle.","stem_image_url":null,"options":[{"id":"FAM-ENG-01-A","label":"A","text":"Fearful","is_correct":false,"image_url":null},{"id":"FAM-ENG-01-B","label":"B","text":"Brave","is_correct":true,"image_url":null},{"id":"FAM-ENG-01-C","label":"C","text":"Weak","is_correct":false,"image_url":null},{"id":"FAM-ENG-01-D","label":"D","text":"Hesitant","is_correct":false,"image_url":null}]}'::jsonb || jsonb_build_object('subject_name',name) FROM subjects WHERE code='ACADEMIC_ENGLISH' ON CONFLICT DO NOTHING;
INSERT INTO portal_practice_questions(code,subject_id,content) SELECT 'FAM-ENG-02',id,'{"id":"70000000-0000-0000-0000-000000000052","code":"FAM-ENG-02","stem":"Identify the preposition in the sentence: \"The cadet marched into the parade ground.\"","explanation":"\"Into\" is a preposition indicating motion toward the interior.","stem_image_url":null,"options":[{"id":"FAM-ENG-02-A","label":"A","text":"marched","is_correct":false,"image_url":null},{"id":"FAM-ENG-02-B","label":"B","text":"into","is_correct":true,"image_url":null},{"id":"FAM-ENG-02-C","label":"C","text":"parade","is_correct":false,"image_url":null},{"id":"FAM-ENG-02-D","label":"D","text":"cadet","is_correct":false,"image_url":null}]}'::jsonb || jsonb_build_object('subject_name',name) FROM subjects WHERE code='ACADEMIC_ENGLISH' ON CONFLICT DO NOTHING;
INSERT INTO portal_practice_questions(code,subject_id,content) SELECT 'FAM-ENG-03',id,'{"id":"70000000-0000-0000-0000-000000000053","code":"FAM-ENG-03","stem":"Choose the correct passive voice: \"The officer inspected the troops.\"","explanation":"Past simple active becomes \"was/were inspected by\": The troops were inspected by the officer.","stem_image_url":null,"options":[{"id":"FAM-ENG-03-A","label":"A","text":"The troops were inspected by the officer.","is_correct":true,"image_url":null},{"id":"FAM-ENG-03-B","label":"B","text":"The troops are inspected by the officer.","is_correct":false,"image_url":null},{"id":"FAM-ENG-03-C","label":"C","text":"The troops had inspected the officer.","is_correct":false,"image_url":null},{"id":"FAM-ENG-03-D","label":"D","text":"The troops have been inspected by the officer.","is_correct":false,"image_url":null}]}'::jsonb || jsonb_build_object('subject_name',name) FROM subjects WHERE code='ACADEMIC_ENGLISH' ON CONFLICT DO NOTHING;
INSERT INTO portal_practice_questions(code,subject_id,content) SELECT 'FAM-ENG-04',id,'{"id":"70000000-0000-0000-0000-000000000054","code":"FAM-ENG-04","stem":"Select the antonym for \"OBEDIENT\":","explanation":"Obedient means compliant; rebellious/defiant is its antonym.","stem_image_url":null,"options":[{"id":"FAM-ENG-04-A","label":"A","text":"Submissive","is_correct":false,"image_url":null},{"id":"FAM-ENG-04-B","label":"B","text":"Dutiful","is_correct":false,"image_url":null},{"id":"FAM-ENG-04-C","label":"C","text":"Defiant","is_correct":true,"image_url":null},{"id":"FAM-ENG-04-D","label":"D","text":"Loyal","is_correct":false,"image_url":null}]}'::jsonb || jsonb_build_object('subject_name',name) FROM subjects WHERE code='ACADEMIC_ENGLISH' ON CONFLICT DO NOTHING;
