INSERT INTO portal_practice_questions(code,subject_id,content) SELECT 'PORTAL-GK-1',id,'{"id":"PORTAL-GK-1","code":"PORTAL-GK-1","stem":"What is the capital of Pakistan?","explanation":"Islamabad is the capital of Pakistan.","stem_image_url":null,"options":[{"id":"PORTAL-GK-1-0","label":"A","text":"Islamabad","is_correct":true,"image_url":null},{"id":"PORTAL-GK-1-1","label":"B","text":"Karachi","is_correct":false,"image_url":null},{"id":"PORTAL-GK-1-2","label":"C","text":"Lahore","is_correct":false,"image_url":null},{"id":"PORTAL-GK-1-3","label":"D","text":"Quetta","is_correct":false,"image_url":null}]}'::jsonb || jsonb_build_object('subject_name',name) FROM subjects WHERE code='GENERAL_KNOWLEDGE' ON CONFLICT DO NOTHING;
